INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`Emote1`) VALUES (27980,'There''s no way you coulda killed all the spiders in the gorge, but you definitely made a dent.$b$bFine, here''s what I promised ya.  Don''t spend it all in one place.  Unless it''s at Thorium Point.',1) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`),`Emote1`=VALUES(`Emote1`);
INSERT INTO `quest_request_items` (`ID`,`CompletionText`) VALUES (27980,'Come on, get out there and kill those spiders!  You aren''t afraid of money, are you?  Because that would be weird.') ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
