INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`Emote1`,`Emote2`) VALUES (27981,'Yeeeeeeowch!  Don''t just go puttin'' this stuff into a dwarf''s open hand.  This stuff is burnin'' up!$b$bNow me hands are gonna get even more swollen...',5,18) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`),`Emote1`=VALUES(`Emote1`),`Emote2`=VALUES(`Emote2`);
