INSERT INTO `quest_offer_reward` (`ID`,`RewardText`) VALUES (27982,'Hmm... the gems looked... sparklier from afar.  Up close, they look kind of dingy.$b$bAh well!  A little spit and polish should do the trick, and if not, I can use ''em to practice my disenchanting.') ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
