INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`Emote1`) VALUES (27986,'And who might you be?$b$bAh, an emissary from the Thorium Brotherhood.  They''re looking for my support?  Fine, I might be willin'' to help out...$b$b...for a price.',1) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`),`Emote1`=VALUES(`Emote1`);
