INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`Emote1`) VALUES (28099,'It is, unfortunately, as I expected.  These bracers bear the indelible mark of the firelord and his minions.$b$bVery well.  With no Horde or Alliance forces anywhere near this godforsaken gorge, it falls upon the Thorium Brotherhood to stop this Archduke before he spreads any more of his evil.',6) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`),`Emote1`=VALUES(`Emote1`);
