INSERT INTO `quest_request_items` (`ID`,`CompletionText`,`EmoteOnIncomplete`) VALUES (7737,'You''ve worked your way up through the Brotherhood''s corporate hierarchy, $r. We have begun to look favorably upon you. Quite an accomplishment!$B$BIf you''re interested in more work and earning more respect amongst us, listen up.$B$BWe can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths.$B$BBring me all the Dark Iron residue you find!',1) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`),`EmoteOnIncomplete`=VALUES(`EmoteOnIncomplete`);
