INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`Emote1`) VALUES (28514,'Oh, Oilfist sent you?  Hah!$b$bDid he ever tell you how he got the name Oilfist?  You''ll have to ask him about that one sometime.',1) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`),`Emote1`=VALUES(`Emote1`);
